-- =====================================================================
-- Locale_401.lua — v4.0.1 Chat, Layout & Aura Quality of Life
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["section_blizzard_auras"]   = "Blizzard Aura Frames",
    ["info_blizzard_auras"]      = "Control Blizzard's default buff and debuff frames without affecting TomoMod unit-frame auras. Changes apply immediately and do not require a reload.",
    ["opt_blizzard_auras_manage"] = "Let TomoMod manage Blizzard aura frames",
    ["opt_blizzard_buffs"]       = "Show Blizzard buffs",
    ["opt_blizzard_debuffs"]     = "Show Blizzard debuffs",
    ["layout_configure"]         = "Configure this element",
    ["wn_401_layout_cogs"]       = "New — Layout Mode now shows a cog button when you hover a movable element. Click it to jump straight to the relevant TomoMod options page.",
    ["wn_401_blizzard_auras"]    = "New — Interface > General can now hide Blizzard's default buff and debuff frames independently, live and without a reload.",
    ["wn_401_chat_v4"]           = "New — Chat V4 rebuilds the chat presentation with a dark TomoMod shell for messages, docked tabs, the native input box and a new sidebar, while Blizzard remains responsible for chat delivery, formatting and secure interactions.",
    ["wn_401_chat_options"]      = "New — Skins > Chat Frame is now the live control centre for Chat V4. Enable it, tune background opacity and font size, choose message behaviour, customize the sidebar and set Copy Chat's line limit; every change applies immediately without a reload.",
    ["wn_401_chat_message_opacity"] = "New — Frame opacity and message-area opacity are now separate. The second slider changes only the background behind chat text, down to fully transparent, without fading tabs, sidebar or input; existing profiles keep their previous appearance.",
    ["wn_401_chat_messages"]     = "New — Message presentation can add or preserve timestamps, abbreviate localized channel names, fade after two minutes, turn familiar smileys into symbols and colour known player mentions by class. Changing an option rebuilds existing lines so the whole visible history stays consistent.",
    ["wn_401_chat_urls"]         = "New — Plain HTTP(S) and www addresses become teal clickable links without disturbing Blizzard's existing hyperlinks. Clicking one opens a focused Ctrl+C popup, and sentence-ending punctuation stays outside the link.",
    ["wn_401_chat_sidebar_options"] = "New — Move the sidebar left or right, adjust its width, button size and spacing, show or hide every shortcut, and choose between 50 and 1,000 Copy Chat lines. Existing Chat Skin message settings migrate once into Chat V4.",
    ["wn_401_chat_wiring"]       = "Changed — Chat V4 is now the single public chat module across defaults, the module registry, dashboard, installer, presets, profile imports and resolution scaling. Legacy chat databases remain internal migration sources only.",
    ["wn_401_chat_combatlog"]    = "Changed — The Combat Log now uses the Chat V4 surface when selected, while Blizzard still filters and formats every line first. TomoMod mirrors only the final output and never replaces the combat-log APIs.",
    ["wn_401_chat_journal_controls"] = "New — Blizzard's Combat Log quick-filter bar now docks at the top of the Chat V4 message area, which reserves space for it. It hides on other tabs and returns to its exact original position and visibility when Chat V4 is disabled, without reparenting or replacing the filters.",
    ["wn_401_chat_phase21_polish"] = "Changed — Mirrored tabs now stay inside the panel's top border. The Emotes shortcut has been removed from the sidebar and options, including old saved layouts, while Copy Chat, Loot, Settings and Scroll to Bottom are arranged cleanly in pairs.",
    ["wn_401_chat_tabs"]         = "New — Chat V4 tabs are now interactive controls arranged left-to-right inside their own strip, including an undocked Combat Log. Left and right clicks are forwarded to the invisible Blizzard tab, preserving native selection and context menus while keeping the active underline and unread indicator in sync.",
    ["wn_401_chat_native_chrome"] = "Fixed — Native chat backgrounds, NineSlice borders and resize handles stay hidden even after selecting General or Combat Log. Chat V4 captures each original alpha before hiding the artwork and restores it exactly when disabled.",
    ["wn_401_chat_sidebar"]      = "New — The redesigned sidebar adds custom icons and live state colours for Friends, Guild, Online/AFK/DND, voice, mute and deafen, plus online counts and shortcuts for Chat Copy, Loot Browser, TomoMod settings and scroll-to-bottom.",
    ["wn_401_chat_sidebar_assets"] = "Changed — Sidebar icons now use dedicated replaceable 64×64 transparent textures, including status, mute and deafen variants. All ten hover titles and descriptions, plus the Online/Away/Do Not Disturb menu, are localized in all six supported languages.",
    ["wn_401_chat_copy"]         = "New — Copy Chat is restored as a full TomoMod window: it reads the active Blizzard tab live when opened, is movable and resizable, follows the chat font size, and provides localized Select All and Close controls with a modern scrollbar and a compatible fallback.",
    ["wn_401_chat_copy_clean"]   = "Changed — Copied chat becomes readable text while preserving message colours, raid markers, link labels and resolvable Battle.net names. UI artwork and control codes are removed, protected values are skipped, shorter transcripts are selected automatically, and the view opens at the newest line.",
    ["wn_401_chat_safe"]         = "Changed — Chat V4 mirrors Blizzard's chat instead of replacing its secure path. Blizzard remains the Combat Log filtering authority, no FCF function is hooked, and disabling Chat V4 restores the native chat presentation.",
    ["wn_401_objective_chrome"]  = "Fixed — Blizzard's full Objective Tracker backdrop and animated header backgrounds can no longer reappear behind TomoMod after a tracker refresh. Their original alpha values are restored when the TomoMod tracker is disabled.",
    ["wn_401_castbar_lifecycle"]  = "Fixed — Your cast bar no longer disappears halfway through a long cast. An instant spell or a proc going off while you were still casting was closing the bar of the spell you were actually casting; only the real end of that cast closes it now.",
    ["wn_401_castbar_identity"]   = "Fixed — A cast bar now only reacts to its own cast. The stop, failure or interrupt of another spell can no longer close it or flash it red, because each bar remembers which cast opened it and checks every ending event against that.",
    ["wn_401_castbar_stale"]      = "New — A cast bar that stops hearing from the server closes itself a second after the cast should have ended. A lost message during a latency spike or a reconnection mid-cast used to be able to leave a bar frozen on screen; empowered spells are left alone, since they are meant to hold past their announced end until you release them.",
    ["wn_401_castbar_preview"]    = "Fixed — Layout Mode and the options preview no longer fight over the player cast bar. You can move it from Layout Mode without opening the options window, closing one no longer cancels the other, and entering combat closes any preview at once so it can never sit on top of a real cast.",
    ["wn_401_layout_chat_route"]  = "Fixed — The Layout Mode cog is back on the chat window. It was still pointing at the frames of the old chat skin, which Chat V4 replaced, so hovering the chat panel offered no shortcut to its settings.",
    ["wn_401_bags_v4"]            = "New — Bags V4 replaces the old bag skin with a window TomoMod owns from end to end: every bag in one grid, the number of used and total slots in the header, your money in the footer, and a frame you can drag wherever you like. Blizzard still owns every item action, so clicking, dragging, selling and tooltips work exactly as they always have.",
    ["wn_401_bags_search_sort"]   = "New — Search your bags as you type, by item name or item ID, and cycle the display between bag order, quality, name and item level from the header button. The sort is purely visual: nothing is ever moved inside your real bags, so it cannot be interrupted halfway or argue with the server.",
    ["wn_401_bags_sidebar"]       = "New — A sidebar keeps your pinned and recent items in view. Middle-click any item to pin it and the pin stays with your profile; anything new that arrives in your bags shows up under Recent. Left-click a sidebar tile to find that item in the grid.",
    ["wn_401_bags_slots"]         = "New — Slots are drawn with quality-coloured borders, the item level on weapons and armour, a mark on pinned items and a dimmed icon on locked ones. Stack counts and cooldown swipes still come from the game itself, and reagent bags are included wherever the client has them. Borders, item level and empty slots can each be switched off.",
    ["wn_401_bags_native"]        = "Changed — Opening and closing follows the game. Your bag keybinds, the micro menu, vendors, the mailbox and the bank all still open the window, and Blizzard's own bag frames are parked out of sight while Bags V4 is on and handed straight back the moment you turn it off.",
    ["wn_401_bags_combat"]        = "New — Bags V4 never builds or moves a slot while you are in combat. Anything it cannot do safely is queued and applied the moment the fight ends, while icons, stack counts, locks and cooldowns keep updating throughout.",
    ["wn_401_bags_migration"]     = "Changed — Your existing bag settings move across once: opacity, scale, slot size, spacing, column count, sorting, quality borders, item level, empty slots, the search bar and the window position. Turning bags on and off from the dashboard, the installer or a preset keeps working while the dedicated Bags V4 options page is built.",
    ["wn_401_bags_display_mode"]  = "New — Choose how your bags open. Combined keeps everything in the single TomoMod window; Separate hands them back to Blizzard's individual bag windows and steps out of the way entirely, putting the game's own combined-bags setting back where it belongs.",
    ["wn_401_bags_options"]       = "New — Skins > Bags is now a live settings page. Display mode, columns, slot size and spacing, scale, opacity, visual sorting, the search bar, quality borders, item level, empty slots and how many pinned and recent tiles the sidebar keeps — every one of them applies immediately, with no reload.",
    ["wn_401_bags_render"]        = "Fixed — Bag slots could show up completely empty. The icons, stack counts and cooldown sweeps are now drawn by TomoMod itself instead of relying on parts of Blizzard's bag button that change from one client version to the next.",
    ["wn_401_bags_interactions"]  = "Fixed — Slots respond properly to the mouse again. Hovering, clicking and dragging could be swallowed by TomoMod's own artwork; the game's button now sits above everything TomoMod draws, tooltips are raised by the addon itself, and middle-clicking a slot pins the item straight from the grid.",
    ["wn_401_bags_empty_quality"] = "Changed — Empty slots are easy to see again, and quality borders read much more clearly: full strength above common quality, softer below it, over a darker slot. The item level moved to the top-left corner so it no longer sits under the stack count, and it is found again on items whose data the game was slow to hand over.",
    ["wn_401_bags_fit"]           = "New — The bag window can no longer be built larger than your screen. Your column count is kept in your profile, but the window shown is reduced to what your resolution and scale can actually fit instead of running off the display.",
})

TomoMod_RegisterLocale("frFR", {
    ["section_blizzard_auras"]   = "Cadres d'auras Blizzard",
    ["info_blizzard_auras"]      = "Contrôle les cadres Blizzard d'améliorations et d'affaiblissements sans toucher aux auras des cadres d'unité TomoMod. Les changements sont immédiats et ne demandent aucun rechargement.",
    ["opt_blizzard_auras_manage"] = "Laisser TomoMod gérer les cadres d'auras Blizzard",
    ["opt_blizzard_buffs"]       = "Afficher les améliorations Blizzard",
    ["opt_blizzard_debuffs"]     = "Afficher les affaiblissements Blizzard",
    ["layout_configure"]         = "Configurer cet élément",
    ["wn_401_layout_cogs"]       = "Nouveau — Le mode Layout affiche désormais un bouton engrenage au survol d'un élément déplaçable. Un clic ouvre directement la page d'options TomoMod correspondante.",
    ["wn_401_blizzard_auras"]    = "Nouveau — Interface > Général permet désormais de masquer séparément les cadres Blizzard d'améliorations et d'affaiblissements, à chaud et sans rechargement.",
    ["wn_401_chat_v4"]           = "Nouveau — Chat V4 reconstruit la présentation du chat avec une interface TomoMod sombre pour les messages, les onglets ancrés, la zone de saisie native et une nouvelle barre latérale, tandis que Blizzard reste responsable de l'acheminement, du formatage et des interactions sécurisées.",
    ["wn_401_chat_options"]      = "Nouveau — Skins > Fenêtre de chat devient le centre de contrôle en direct de Chat V4. Activez-le, réglez l'opacité du fond et la taille du texte, choisissez le comportement des messages, personnalisez la barre latérale et fixez la limite de lignes de la copie du chat : tout s'applique immédiatement, sans rechargement.",
    ["wn_401_chat_message_opacity"] = "Nouveau — L'opacité du cadre et celle de la zone des messages sont maintenant séparées. Le second curseur ne modifie que le fond derrière le texte du chat, jusqu'à une transparence totale, sans estomper les onglets, la barre latérale ni la zone de saisie ; les profils existants conservent leur apparence précédente.",
    ["wn_401_chat_messages"]     = "Nouveau — La présentation peut ajouter ou conserver les horodatages, abréger les noms de canaux traduits, s'estomper après deux minutes, transformer les smileys courants en symboles et colorer par classe les mentions de joueurs connus. Modifier une option reconstruit les lignes existantes pour garder tout l'historique visible cohérent.",
    ["wn_401_chat_urls"]         = "Nouveau — Les adresses HTTP(S) et www ordinaires deviennent des liens turquoise cliquables sans perturber les liens Blizzard existants. Un clic ouvre une fenêtre Ctrl+C ciblée et la ponctuation de fin de phrase reste hors du lien.",
    ["wn_401_chat_sidebar_options"] = "Nouveau — Placez la barre latérale à gauche ou à droite, réglez sa largeur, la taille et l'espacement des boutons, affichez ou masquez chaque raccourci et choisissez entre 50 et 1 000 lignes pour la copie du chat. Les anciens réglages de messages du Chat Skin migrent une seule fois vers Chat V4.",
    ["wn_401_chat_wiring"]       = "Modifié — Chat V4 est désormais l'unique module de chat public dans les valeurs par défaut, le registre des modules, l'accueil, l'installateur, les préréglages, les imports de profils et l'adaptation à la résolution. Les anciennes bases de données du chat ne servent plus qu'à la migration interne.",
    ["wn_401_chat_combatlog"]    = "Modifié — Le journal de combat utilise désormais la surface Chat V4 lorsqu'il est sélectionné, tandis que Blizzard filtre et formate toujours chaque ligne en premier. TomoMod reflète uniquement le résultat final et ne remplace jamais les API du journal de combat.",
    ["wn_401_chat_journal_controls"] = "Nouveau — La barre de filtres rapides du journal de combat Blizzard s'ancre désormais en haut de la zone de messages Chat V4, qui lui réserve sa place. Elle se masque sur les autres onglets et retrouve exactement sa position et sa visibilité d'origine lorsque Chat V4 est désactivé, sans être rattachée à un autre cadre ni remplacer les filtres.",
    ["wn_401_chat_phase21_polish"] = "Modifié — Les onglets reflétés restent maintenant dans la bordure supérieure du panneau. Le raccourci Emotes est retiré de la barre latérale et des options, y compris des dispositions enregistrées, tandis que Copie du chat, Butin, Réglages et Dernier message sont proprement regroupés par deux.",
    ["wn_401_chat_tabs"]         = "Nouveau — Les onglets Chat V4 sont maintenant des contrôles interactifs disposés de gauche à droite dans leur propre barre, y compris pour un journal de combat détaché. Les clics gauche et droit sont relayés vers l'onglet Blizzard invisible, préservant la sélection et les menus contextuels natifs tout en synchronisant le soulignement actif et les messages non lus.",
    ["wn_401_chat_native_chrome"] = "Corrigé — Les fonds, bordures NineSlice et poignées de redimensionnement du chat natif restent masqués même après avoir sélectionné Général ou Journal. Chat V4 mémorise l'alpha original de chaque élément et le restaure exactement à la désactivation.",
    ["wn_401_chat_sidebar"]      = "Nouveau — La barre latérale repensée ajoute des icônes personnalisées et des couleurs d'état dynamiques pour les amis, la guilde, En ligne/ABS/NPD, la voix, le micro et le mode sourd, ainsi que les compteurs en ligne et des raccourcis vers la copie du chat, le navigateur de butin, les réglages TomoMod et le dernier message.",
    ["wn_401_chat_sidebar_assets"] = "Modifié — Les icônes de la barre latérale utilisent désormais des textures transparentes 64×64 dédiées et remplaçables, avec des variantes pour le statut, le micro et le mode sourd. Les titres et descriptions des dix infobulles, ainsi que le menu En ligne/Absent/Ne pas déranger, sont traduits dans les six langues prises en charge.",
    ["wn_401_chat_copy"]         = "Nouveau — La copie du chat retrouve une fenêtre TomoMod complète : elle lit en direct l'onglet Blizzard actif à l'ouverture, peut être déplacée et redimensionnée, suit la taille de police du chat et propose des boutons Tout sélectionner/Fermer traduits, avec une barre de défilement moderne et un repli compatible.",
    ["wn_401_chat_copy_clean"]   = "Modifié — Le chat copié devient un texte lisible tout en conservant les couleurs des messages, les marqueurs de raid, les libellés des liens et les noms Battle.net disponibles. Les éléments graphiques et codes de contrôle sont retirés, les valeurs protégées ignorées, les textes courts sélectionnés automatiquement et la vue s'ouvre sur la ligne la plus récente.",
    ["wn_401_chat_safe"]         = "Modifié — Chat V4 reflète le chat Blizzard au lieu de remplacer son chemin sécurisé. Blizzard reste responsable du filtrage du journal de combat, aucune fonction FCF n'est accrochée et désactiver Chat V4 restaure la présentation native du chat.",
    ["wn_401_objective_chrome"]  = "Corrigé — Le fond complet et les arrière-plans d'en-têtes animés du suivi des objectifs Blizzard ne peuvent plus réapparaître derrière TomoMod après une actualisation. Leurs valeurs d'alpha d'origine sont restaurées lorsque le suivi TomoMod est désactivé.",
    ["wn_401_castbar_lifecycle"]  = "Correctif — Votre barre d'incantation ne disparaît plus au milieu d'un sort long. Un sort instantané ou un proc déclenché pendant que vous incantiez fermait la barre du sort réellement en cours ; seule la vraie fin de cette incantation la ferme désormais.",
    ["wn_401_castbar_identity"]   = "Correctif — Une barre d'incantation ne réagit plus qu'à sa propre incantation. L'arrêt, l'échec ou l'interruption d'un autre sort ne peut plus la fermer ni la faire clignoter en rouge : chaque barre retient quelle incantation l'a ouverte et confronte chaque événement de fin à cette identité.",
    ["wn_401_castbar_stale"]      = "Nouveau — Une barre d'incantation qui n'a plus de nouvelles du serveur se referme une seconde après la fin prévue du sort. Un message perdu lors d'un pic de latence ou une reconnexion en pleine incantation pouvait laisser une barre figée à l'écran ; les sorts à charge sont épargnés, puisqu'ils sont censés se maintenir au-delà de leur fin annoncée jusqu'au relâchement.",
    ["wn_401_castbar_preview"]    = "Correctif — Le mode Layout et l'aperçu des options ne se disputent plus la barre d'incantation du joueur. Vous pouvez la déplacer depuis le mode Layout sans ouvrir la fenêtre d'options, fermer l'un n'annule plus l'autre, et l'entrée en combat referme immédiatement tout aperçu pour qu'il ne recouvre jamais une vraie incantation.",
    ["wn_401_layout_chat_route"]  = "Correctif — L'engrenage du mode Layout est de retour sur la fenêtre de chat. Il visait encore les cadres de l'ancien habillage du chat, remplacé par Chat V4 : survoler le panneau de chat n'offrait donc aucun raccourci vers ses réglages.",
    ["wn_401_bags_v4"]            = "Nouveau — Bags V4 remplace l'ancien habillage des sacs par une fenêtre entièrement gérée par TomoMod : tous les sacs dans une seule grille, le nombre d'emplacements occupés et disponibles dans l'en-tête, votre argent en pied de fenêtre, et un cadre que vous déplacez où vous voulez. Blizzard reste maître de toutes les actions sur les objets : clic, glisser-déposer, vente et infobulles fonctionnent exactement comme avant.",
    ["wn_401_bags_search_sort"]   = "Nouveau — Cherchez dans vos sacs au fil de la frappe, par nom d'objet ou par identifiant, et faites défiler l'affichage entre ordre des sacs, qualité, nom et niveau d'objet depuis le bouton d'en-tête. Le tri est purement visuel : aucun objet n'est jamais déplacé dans vos vrais sacs, il ne peut donc pas être interrompu en cours de route ni entrer en conflit avec le serveur.",
    ["wn_401_bags_sidebar"]       = "Nouveau — Une barre latérale garde sous les yeux vos objets épinglés et récents. Un clic milieu épingle n'importe quel objet et l'épingle reste attachée à votre profil ; tout nouvel objet arrivant dans vos sacs apparaît dans Récents. Un clic gauche sur une vignette retrouve l'objet dans la grille.",
    ["wn_401_bags_slots"]         = "Nouveau — Les emplacements affichent des bordures aux couleurs de qualité, le niveau d'objet sur les armes et les armures, une marque sur les objets épinglés et une icône grisée sur les objets verrouillés. Les quantités et les balayages de recharge viennent toujours du jeu lui-même, et les sacs à composants sont inclus quand le client les propose. Bordures, niveau d'objet et emplacements vides se désactivent séparément.",
    ["wn_401_bags_native"]        = "Modifié — L'ouverture et la fermeture suivent le jeu. Vos raccourcis de sacs, le micro-menu, les marchands, la boîte aux lettres et la banque ouvrent toujours la fenêtre, et les cadres de sacs Blizzard sont mis de côté tant que Bags V4 est actif, puis rendus intacts dès que vous le désactivez.",
    ["wn_401_bags_combat"]        = "Nouveau — Bags V4 ne crée ni ne déplace jamais un emplacement pendant un combat. Tout ce qui ne peut pas se faire sans risque est mis en attente et appliqué dès la fin du combat, tandis que les icônes, les quantités, les verrouillages et les recharges continuent de se mettre à jour.",
    ["wn_401_bags_migration"]     = "Modifié — Vos réglages de sacs existants sont repris une fois : opacité, échelle, taille des emplacements, espacement, nombre de colonnes, tri, bordures de qualité, niveau d'objet, emplacements vides, barre de recherche et position de la fenêtre. Activer et désactiver les sacs depuis le tableau de bord, l'installateur ou un préréglage continue de fonctionner le temps que la page d'options dédiée à Bags V4 soit construite.",
    ["wn_401_bags_display_mode"]  = "Nouveau — Choisissez comment vos sacs s'ouvrent. Combiné garde tout dans l'unique fenêtre TomoMod ; Séparé les rend aux fenêtres individuelles de Blizzard et s'efface complètement, en remettant le réglage de sacs combinés du jeu à sa place.",
    ["wn_401_bags_options"]       = "Nouveau — Skins > Sacs est désormais une page de réglages vivante. Mode d'affichage, colonnes, taille et espacement des emplacements, échelle, opacité, tri visuel, barre de recherche, bordures de qualité, niveau d'objet, emplacements vides et nombre de vignettes épinglées et récentes : chaque réglage s'applique immédiatement, sans rechargement.",
    ["wn_401_bags_render"]        = "Correctif — Des emplacements pouvaient apparaître complètement vides. Les icônes, les quantités et les balayages de recharge sont maintenant dessinés par TomoMod lui-même au lieu de dépendre de parties du bouton de sac Blizzard qui changent d'une version du client à l'autre.",
    ["wn_401_bags_interactions"]  = "Correctif — Les emplacements répondent de nouveau correctement à la souris. Le survol, le clic et le glisser pouvaient être absorbés par les décorations de TomoMod ; le bouton du jeu passe désormais au-dessus de tout ce que TomoMod dessine, les infobulles sont affichées par l'addon lui-même, et le clic milieu épingle l'objet directement depuis la grille.",
    ["wn_401_bags_empty_quality"] = "Modifié — Les emplacements vides se repèrent de nouveau facilement, et les bordures de qualité sont bien plus lisibles : pleine intensité au-dessus de la qualité commune, plus douces en dessous, sur un fond assombri. Le niveau d'objet est passé en haut à gauche pour ne plus se retrouver sous la quantité, et il réapparaît sur les objets dont le jeu tardait à fournir les données.",
    ["wn_401_bags_fit"]           = "Nouveau — La fenêtre des sacs ne peut plus être construite plus grande que votre écran. Votre nombre de colonnes reste enregistré dans votre profil, mais la fenêtre affichée est réduite à ce que votre résolution et votre échelle peuvent réellement contenir au lieu de déborder de l'écran.",
})

TomoMod_RegisterLocale("deDE", {
    ["section_blizzard_auras"]   = "Blizzard-Aurafenster",
    ["info_blizzard_auras"]      = "Steuert Blizzards standardmäßige Stärkungs- und Schwächungszauberfenster, ohne die Auren der TomoMod-Einheitenfenster zu beeinflussen. Änderungen gelten sofort und benötigen kein Neuladen.",
    ["opt_blizzard_auras_manage"] = "Blizzard-Aurafenster von TomoMod verwalten lassen",
    ["opt_blizzard_buffs"]       = "Blizzard-Stärkungszauber anzeigen",
    ["opt_blizzard_debuffs"]     = "Blizzard-Schwächungszauber anzeigen",
    ["layout_configure"]         = "Dieses Element konfigurieren",
    ["wn_401_layout_cogs"]       = "Neu — Im Layout-Modus erscheint beim Überfahren eines verschiebbaren Elements jetzt ein Zahnrad. Ein Klick öffnet direkt die passende TomoMod-Einstellungsseite.",
    ["wn_401_blizzard_auras"]    = "Neu — Unter Interface > Allgemein können Blizzards Buff- und Debuff-Fenster nun getrennt, live und ohne Neuladen ausgeblendet werden.",
    ["wn_401_chat_v4"]           = "Neu — Chat V4 baut die Chat-Darstellung mit einer dunklen TomoMod-Oberfläche für Nachrichten, angedockte Reiter, das native Eingabefeld und eine neue Seitenleiste neu auf, während Blizzard weiterhin Zustellung, Formatierung und sichere Interaktionen übernimmt.",
    ["wn_401_chat_options"]      = "Neu — Skins > Chatfenster ist jetzt die Live-Steuerzentrale für Chat V4. Aktivierung, Hintergrundtransparenz, Schriftgröße, Nachrichtenverhalten, Seitenleiste und Zeilenlimit der Chat-Kopie lassen sich dort einstellen; jede Änderung gilt sofort und ohne Neuladen.",
    ["wn_401_chat_message_opacity"] = "Neu — Die Deckkraft des Rahmens und des Nachrichtenbereichs sind jetzt getrennt. Der zweite Regler verändert nur den Hintergrund hinter dem Chattext bis hin zu vollständiger Transparenz, ohne Reiter, Seitenleiste oder Eingabefeld auszublenden; vorhandene Profile behalten ihr bisheriges Erscheinungsbild.",
    ["wn_401_chat_messages"]     = "Neu — Die Nachrichtendarstellung kann Zeitstempel ergänzen oder erhalten, lokalisierte Kanalnamen abkürzen, nach zwei Minuten ausblenden, bekannte Smileys in Symbole verwandeln und Erwähnungen bekannter Spieler in Klassenfarbe anzeigen. Eine Änderung baut vorhandene Zeilen neu auf, damit der gesamte sichtbare Verlauf einheitlich bleibt.",
    ["wn_401_chat_urls"]         = "Neu — Einfache HTTP(S)- und www-Adressen werden zu türkisen anklickbaren Links, ohne Blizzards vorhandene Hyperlinks zu verändern. Ein Klick öffnet ein fokussiertes Strg+C-Fenster; Satzzeichen am Satzende bleiben außerhalb des Links.",
    ["wn_401_chat_sidebar_options"] = "Neu — Die Seitenleiste kann links oder rechts stehen; Breite, Schaltflächengröße und Abstand sowie jeder einzelne Schnellzugriff sind einstellbar. Für die Chat-Kopie sind 50 bis 1.000 Zeilen wählbar. Vorhandene Nachrichtenoptionen des Chat-Skins werden einmalig zu Chat V4 migriert.",
    ["wn_401_chat_wiring"]       = "Geändert — Chat V4 ist jetzt in Standardwerten, Modulregister, Startseite, Installationsassistent, Voreinstellungen, Profilimporten und Auflösungsskalierung das einzige öffentliche Chatmodul. Die alten Chatdatenbanken dienen nur noch intern als Migrationsquellen.",
    ["wn_401_chat_combatlog"]    = "Geändert — Das Kampflog verwendet jetzt bei Auswahl die Chat-V4-Oberfläche, während Blizzard weiterhin jede Zeile zuerst filtert und formatiert. TomoMod spiegelt nur die endgültige Ausgabe und ersetzt niemals die Kampflog-APIs.",
    ["wn_401_chat_journal_controls"] = "Neu — Blizzards Schnellfilterleiste des Kampflogs ist jetzt oben im Chat-V4-Nachrichtenbereich angedockt, der dafür Platz reserviert. Auf anderen Reitern wird sie ausgeblendet und beim Deaktivieren von Chat V4 exakt an ihrer ursprünglichen Position und Sichtbarkeit wiederhergestellt, ohne sie einem anderen Frame unterzuordnen oder die Filter zu ersetzen.",
    ["wn_401_chat_phase21_polish"] = "Geändert — Gespiegelte Reiter bleiben jetzt innerhalb des oberen Panelrahmens. Der Emotes-Schnellzugriff wurde aus Seitenleiste, Optionen und gespeicherten Layouts entfernt; Chat-Kopie, Beute, Einstellungen und Neueste Nachricht sind sauber paarweise angeordnet.",
    ["wn_401_chat_tabs"]         = "Neu — Chat-V4-Reiter sind jetzt interaktive Steuerelemente, die in ihrer eigenen Leiste von links nach rechts angeordnet werden, einschließlich eines abgedockten Kampflogs. Links- und Rechtsklicks werden an den unsichtbaren Blizzard-Reiter weitergeleitet, sodass native Auswahl und Kontextmenüs erhalten bleiben und aktive Unterstreichung sowie Ungelesen-Anzeige synchron sind.",
    ["wn_401_chat_native_chrome"] = "Behoben — Native Chathintergründe, NineSlice-Rahmen und Größenänderungsgriffe bleiben auch nach Auswahl von Allgemein oder Kampflog ausgeblendet. Chat V4 speichert jeden ursprünglichen Alphawert und stellt ihn beim Deaktivieren exakt wieder her.",
    ["wn_401_chat_sidebar"]      = "Neu — Die überarbeitete Seitenleiste bietet eigene Symbole und Live-Statusfarben für Freunde, Gilde, Online/AFK/DND, Sprachchat, Stummschaltung und Taubschaltung sowie Online-Zähler und Schnellzugriffe auf Chat-Kopie, Beute-Browser, TomoMod-Einstellungen und die neueste Nachricht.",
    ["wn_401_chat_sidebar_assets"] = "Geändert — Die Symbole der Seitenleiste verwenden jetzt eigene austauschbare transparente 64×64-Texturen, einschließlich Varianten für Status, Mikrofon und Audio. Alle zehn Titel und Beschreibungen der Kurzinfos sowie das Menü Online/Abwesend/Bitte nicht stören sind in allen sechs unterstützten Sprachen übersetzt.",
    ["wn_401_chat_copy"]         = "Neu — Chat-Kopie ist wieder ein vollständiges TomoMod-Fenster: Es liest beim Öffnen den aktiven Blizzard-Reiter live, ist verschiebbar und skalierbar, folgt der Chat-Schriftgröße und bietet übersetzte Schaltflächen für Alles markieren und Schließen sowie eine moderne Bildlaufleiste mit kompatiblem Ersatz.",
    ["wn_401_chat_copy_clean"]   = "Geändert — Kopierter Chat wird zu lesbarem Text und behält Nachrichtenfarben, Schlachtzugsmarkierungen, Linkbeschriftungen und auflösbare Battle.net-Namen. UI-Grafiken und Steuercodes werden entfernt, geschützte Werte übersprungen, kürzere Texte automatisch markiert und die Ansicht öffnet bei der neuesten Zeile.",
    ["wn_401_chat_safe"]         = "Geändert — Chat V4 spiegelt Blizzards Chat, statt dessen sicheren Pfad zu ersetzen. Blizzard behält die Kontrolle über die Kampflog-Filterung, keine FCF-Funktion wird eingehakt und beim Deaktivieren von Chat V4 wird die native Chat-Darstellung wiederhergestellt.",
    ["wn_401_objective_chrome"]  = "Behoben — Blizzards vollständiger Hintergrund und die animierten Kopfzeilen der Zielverfolgung können nach einer Aktualisierung nicht mehr hinter TomoMod erscheinen. Beim Deaktivieren der TomoMod-Zielverfolgung werden ihre ursprünglichen Alphawerte wiederhergestellt.",
    ["wn_401_castbar_lifecycle"]  = "Behoben — Eure Zauberleiste verschwindet nicht mehr mitten in einem langen Zauber. Ein Sofortzauber oder ein Proc, der während des Zauberns auslöste, schloss die Leiste des tatsächlich laufenden Zaubers; jetzt schließt sie nur noch dessen echtes Ende.",
    ["wn_401_castbar_identity"]   = "Behoben — Eine Zauberleiste reagiert nur noch auf ihren eigenen Zauber. Abbruch, Fehlschlag oder Unterbrechung eines anderen Zaubers kann sie weder schließen noch rot aufblitzen lassen, denn jede Leiste merkt sich, welcher Zauber sie geöffnet hat, und prüft jedes Endereignis dagegen.",
    ["wn_401_castbar_stale"]      = "Neu — Eine Zauberleiste, die nichts mehr vom Server hört, schließt sich eine Sekunde nach dem vorgesehenen Ende des Zaubers. Eine bei einem Latenzsprung verlorene Nachricht oder eine Neuverbindung mitten im Zauber konnte eine Leiste eingefroren auf dem Bildschirm zurücklassen; Entfesselungszauber sind ausgenommen, da sie bis zum Loslassen bewusst über ihr angekündigtes Ende hinaus bestehen bleiben.",
    ["wn_401_castbar_preview"]    = "Behoben — Layout-Modus und Optionsvorschau streiten nicht mehr um die Zauberleiste des Spielers. Ihr könnt sie im Layout-Modus verschieben, ohne das Optionsfenster zu öffnen, das Schließen des einen bricht das andere nicht mehr ab, und beim Betreten des Kampfes wird jede Vorschau sofort geschlossen, damit sie niemals über einem echten Zauber liegt.",
    ["wn_401_layout_chat_route"]  = "Behoben — Das Zahnrad des Layout-Modus ist im Chatfenster zurück. Es zeigte noch auf die Fenster des alten Chat-Skins, das Chat V4 ersetzt hat, sodass das Überfahren des Chatfensters keine Abkürzung zu dessen Einstellungen bot.",
    ["wn_401_bags_v4"]            = "Neu — Bags V4 ersetzt das alte Taschen-Skin durch ein Fenster, das vollständig TomoMod gehört: alle Taschen in einem Raster, die Zahl der belegten und gesamten Plätze in der Kopfzeile, euer Geld in der Fußzeile und ein Rahmen, den ihr frei verschieben könnt. Blizzard behält jede Gegenstandsaktion, also funktionieren Klicken, Ziehen, Verkaufen und Tooltips genau wie bisher.",
    ["wn_401_bags_search_sort"]   = "Neu — Durchsucht eure Taschen während des Tippens nach Gegenstandsnamen oder -ID und schaltet die Anzeige über die Kopfzeile zwischen Taschenreihenfolge, Qualität, Name und Gegenstandsstufe um. Die Sortierung ist rein visuell: In euren echten Taschen wird nichts verschoben, sie kann also nicht auf halbem Weg abbrechen und gerät nicht mit dem Server in Konflikt.",
    ["wn_401_bags_sidebar"]       = "Neu — Eine Seitenleiste hält angeheftete und neue Gegenstände im Blick. Ein Mittelklick heftet einen Gegenstand an, und die Anheftung bleibt an eurem Profil; alles, was neu in die Taschen kommt, erscheint unter Neu. Ein Linksklick auf eine Kachel findet den Gegenstand im Raster.",
    ["wn_401_bags_slots"]         = "Neu — Plätze zeigen qualitätsfarbene Ränder, die Gegenstandsstufe auf Waffen und Rüstung, eine Markierung auf angehefteten und ein abgedunkeltes Symbol auf gesperrten Gegenständen. Stapelzahlen und Abklingzeit-Animationen kommen weiterhin vom Spiel selbst, und Reagenzientaschen sind enthalten, sofern der Client sie kennt. Ränder, Gegenstandsstufe und leere Plätze lassen sich einzeln abschalten.",
    ["wn_401_bags_native"]        = "Geändert — Öffnen und Schließen folgt dem Spiel. Eure Taschen-Tastenbelegungen, das Mikromenü, Händler, der Briefkasten und die Bank öffnen weiterhin das Fenster, und Blizzards eigene Taschenfenster werden beiseitegestellt, solange Bags V4 aktiv ist, und unverändert zurückgegeben, sobald ihr es abschaltet.",
    ["wn_401_bags_combat"]        = "Neu — Bags V4 erstellt und verschiebt im Kampf niemals einen Platz. Was nicht sicher möglich ist, wird eingereiht und unmittelbar nach dem Kampf angewendet, während Symbole, Stapelzahlen, Sperren und Abklingzeiten durchgehend aktualisiert werden.",
    ["wn_401_bags_migration"]     = "Geändert — Eure vorhandenen Taschen-Einstellungen werden einmalig übernommen: Deckkraft, Skalierung, Platzgröße, Abstand, Spaltenzahl, Sortierung, Qualitätsränder, Gegenstandsstufe, leere Plätze, Suchleiste und Fensterposition. Das Ein- und Ausschalten der Taschen über Übersicht, Installer oder eine Vorlage funktioniert weiter, während die eigene Bags-V4-Optionsseite entsteht.",
    ["wn_401_bags_display_mode"]  = "Neu — Wählt, wie eure Taschen sich öffnen. Kombiniert hält alles im einen TomoMod-Fenster; Getrennt gibt sie an Blizzards einzelne Taschenfenster zurück und tritt vollständig zur Seite, wobei die spieleigene Einstellung für kombinierte Taschen wieder ihren Platz einnimmt.",
    ["wn_401_bags_options"]       = "Neu — Skins > Taschen ist jetzt eine lebendige Einstellungsseite. Anzeigemodus, Spalten, Platzgröße und Abstand, Skalierung, Deckkraft, visuelle Sortierung, Suchleiste, Qualitätsränder, Gegenstandsstufe, leere Plätze und die Anzahl der angehefteten und neuen Kacheln — alles wird sofort und ohne Neuladen übernommen.",
    ["wn_401_bags_render"]        = "Behoben — Taschenplätze konnten völlig leer erscheinen. Symbole, Stapelzahlen und Abklingzeit-Animationen zeichnet TomoMod nun selbst, statt sich auf Teile von Blizzards Taschenknopf zu verlassen, die sich von Clientversion zu Clientversion ändern.",
    ["wn_401_bags_interactions"]  = "Behoben — Plätze reagieren wieder richtig auf die Maus. Überfahren, Klicken und Ziehen konnten von TomoMods eigener Grafik geschluckt werden; der Knopf des Spiels liegt jetzt über allem, was TomoMod zeichnet, Tooltips zeigt das Addon selbst an, und ein Mittelklick heftet den Gegenstand direkt aus dem Raster an.",
    ["wn_401_bags_empty_quality"] = "Geändert — Leere Plätze sind wieder gut zu erkennen, und Qualitätsränder lesen sich deutlich klarer: volle Stärke oberhalb gewöhnlicher Qualität, weicher darunter, auf dunklerem Grund. Die Gegenstandsstufe ist nach oben links gewandert und liegt damit nicht mehr unter der Stapelzahl, und sie erscheint wieder bei Gegenständen, deren Daten das Spiel nur verzögert lieferte.",
    ["wn_401_bags_fit"]           = "Neu — Das Taschenfenster kann nicht mehr größer gebaut werden als euer Bildschirm. Eure Spaltenzahl bleibt im Profil gespeichert, doch das angezeigte Fenster wird auf das reduziert, was Auflösung und Skalierung tatsächlich fassen, statt über den Bildschirmrand hinauszulaufen.",
})

TomoMod_RegisterLocale("esES", {
    ["section_blizzard_auras"]   = "Marcos de auras de Blizzard",
    ["info_blizzard_auras"]      = "Controla los marcos predeterminados de beneficios y perjuicios de Blizzard sin afectar a las auras de los marcos de unidad de TomoMod. Los cambios se aplican al instante y no requieren recargar.",
    ["opt_blizzard_auras_manage"] = "Permitir que TomoMod gestione los marcos de auras de Blizzard",
    ["opt_blizzard_buffs"]       = "Mostrar beneficios de Blizzard",
    ["opt_blizzard_debuffs"]     = "Mostrar perjuicios de Blizzard",
    ["layout_configure"]         = "Configurar este elemento",
    ["wn_401_layout_cogs"]       = "Nuevo — El modo Layout muestra ahora un engranaje al pasar el cursor sobre un elemento movible. Un clic abre directamente la página de opciones de TomoMod correspondiente.",
    ["wn_401_blizzard_auras"]    = "Nuevo — Interface > General permite ocultar por separado los marcos de beneficios y perjuicios de Blizzard, en vivo y sin recargar.",
    ["wn_401_chat_v4"]           = "Nuevo — Chat V4 reconstruye la presentación del chat con una interfaz oscura de TomoMod para los mensajes, las pestañas acopladas, el cuadro de entrada nativo y una nueva barra lateral, mientras Blizzard sigue gestionando la entrega, el formato y las interacciones seguras.",
    ["wn_401_chat_options"]      = "Nuevo — Skins > Ventana de chat es ahora el centro de control en vivo de Chat V4. Actívalo, ajusta la opacidad del fondo y el tamaño de letra, elige el comportamiento de los mensajes, personaliza la barra lateral y fija el límite de líneas de Copiar chat; cada cambio se aplica al instante y sin recargar.",
    ["wn_401_chat_message_opacity"] = "Nuevo — La opacidad del marco y la del área de mensajes ahora son independientes. El segundo control solo cambia el fondo detrás del texto del chat, hasta dejarlo totalmente transparente, sin atenuar las pestañas, la barra lateral ni el cuadro de entrada; los perfiles existentes conservan su aspecto anterior.",
    ["wn_401_chat_messages"]     = "Nuevo — La presentación puede añadir o conservar marcas de tiempo, abreviar nombres de canales localizados, desvanecerse tras dos minutos, convertir emoticonos habituales en símbolos y colorear por clase las menciones de jugadores conocidos. Cambiar una opción reconstruye las líneas existentes para mantener uniforme todo el historial visible.",
    ["wn_401_chat_urls"]         = "Nuevo — Las direcciones HTTP(S) y www normales se convierten en enlaces turquesa sin alterar los hipervínculos existentes de Blizzard. Al pulsar se abre una ventana enfocada para Ctrl+C y la puntuación final queda fuera del enlace.",
    ["wn_401_chat_sidebar_options"] = "Nuevo — Coloca la barra lateral a la izquierda o derecha, ajusta su anchura, tamaño y separación de botones, muestra u oculta cada acceso y elige entre 50 y 1.000 líneas para Copiar chat. Los ajustes anteriores de mensajes de Chat Skin se migran una sola vez a Chat V4.",
    ["wn_401_chat_wiring"]       = "Cambio — Chat V4 es ahora el único módulo público de chat en los valores predeterminados, el registro de módulos, el panel de inicio, el instalador, los ajustes predefinidos, las importaciones de perfiles y el escalado por resolución. Las bases de datos antiguas del chat solo se conservan como fuentes internas de migración.",
    ["wn_401_chat_combatlog"]    = "Cambio — El registro de combate usa ahora la superficie de Chat V4 cuando se selecciona, mientras Blizzard sigue filtrando y formateando primero cada línea. TomoMod solo refleja la salida final y nunca sustituye las API del registro de combate.",
    ["wn_401_chat_journal_controls"] = "Nuevo — La barra de filtros rápidos del registro de combate de Blizzard se acopla ahora en la parte superior del área de mensajes de Chat V4, que reserva espacio para ella. Se oculta en otras pestañas y recupera exactamente su posición y visibilidad originales al desactivar Chat V4, sin vincularla a otro marco ni sustituir los filtros.",
    ["wn_401_chat_phase21_polish"] = "Cambio — Las pestañas reflejadas permanecen ahora dentro del borde superior del panel. El acceso Emotes se elimina de la barra lateral, las opciones y los diseños guardados; Copiar chat, Botín, Ajustes y Último mensaje quedan ordenados limpiamente por parejas.",
    ["wn_401_chat_tabs"]         = "Nuevo — Las pestañas de Chat V4 son ahora controles interactivos ordenados de izquierda a derecha en su propia barra, incluido un registro de combate desacoplado. Los clics izquierdo y derecho se reenvían a la pestaña invisible de Blizzard, conservando la selección y los menús contextuales nativos mientras se sincronizan el subrayado activo y los mensajes sin leer.",
    ["wn_401_chat_native_chrome"] = "Corregido — Los fondos, bordes NineSlice y controles de tamaño del chat nativo permanecen ocultos incluso después de seleccionar General o Registro de combate. Chat V4 guarda el alfa original de cada elemento y lo restaura exactamente al desactivarse.",
    ["wn_401_chat_sidebar"]      = "Nuevo — La barra lateral rediseñada añade iconos personalizados y colores de estado en vivo para Amigos, Hermandad, En línea/AUS/NM, voz, silenciar micrófono y ensordecer, además de contadores conectados y accesos a copia del chat, buscador de botín, ajustes de TomoMod y último mensaje.",
    ["wn_401_chat_sidebar_assets"] = "Cambio — Los iconos de la barra lateral usan ahora texturas transparentes de 64×64 dedicadas y reemplazables, con variantes para estado, micrófono y audio. Los títulos y descripciones de las diez ayudas, además del menú En línea/Ausente/No molestar, están traducidos a los seis idiomas compatibles.",
    ["wn_401_chat_copy"]         = "Nuevo — Copiar chat vuelve como una ventana completa de TomoMod: lee en vivo la pestaña activa de Blizzard al abrirse, se puede mover y redimensionar, sigue el tamaño de letra del chat y ofrece botones traducidos para Seleccionar todo y Cerrar, con una barra de desplazamiento moderna y una alternativa compatible.",
    ["wn_401_chat_copy_clean"]   = "Cambio — El chat copiado se convierte en texto legible y conserva los colores de los mensajes, los marcadores de banda, las etiquetas de los enlaces y los nombres de Battle.net disponibles. Se eliminan los gráficos y códigos de control, se omiten los valores protegidos, los textos cortos se seleccionan automáticamente y la vista se abre en la línea más reciente.",
    ["wn_401_chat_safe"]         = "Cambio — Chat V4 refleja el chat de Blizzard en lugar de sustituir su ruta segura. Blizzard conserva el control del filtrado del registro de combate, no se engancha ninguna función FCF y al desactivar Chat V4 se restaura la presentación nativa.",
    ["wn_401_objective_chrome"]  = "Corregido — El fondo completo y los fondos animados de los encabezados del seguimiento de objetivos de Blizzard ya no pueden reaparecer detrás de TomoMod tras una actualización. Sus valores alfa originales se restauran al desactivar el seguimiento de TomoMod.",
    ["wn_401_castbar_lifecycle"]  = "Corrección — Tu barra de lanzamiento ya no desaparece a mitad de un hechizo largo. Un hechizo instantáneo o un proc que saltaba mientras lanzabas cerraba la barra del hechizo que estabas lanzando de verdad; ahora solo la cierra el final real de ese lanzamiento.",
    ["wn_401_castbar_identity"]   = "Corrección — Una barra de lanzamiento solo reacciona ya a su propio lanzamiento. La parada, el fallo o la interrupción de otro hechizo no puede cerrarla ni hacerla parpadear en rojo, porque cada barra recuerda qué lanzamiento la abrió y contrasta con él cada evento de cierre.",
    ["wn_401_castbar_stale"]      = "Nuevo — Una barra de lanzamiento que deja de recibir noticias del servidor se cierra un segundo después del final previsto del hechizo. Un mensaje perdido en un pico de latencia o una reconexión a mitad de lanzamiento podía dejar una barra congelada en pantalla; los hechizos de intensificación quedan al margen, ya que están pensados para mantenerse más allá de su final anunciado hasta que los sueltas.",
    ["wn_401_castbar_preview"]    = "Corrección — El modo Diseño y la vista previa de opciones ya no se disputan la barra de lanzamiento del jugador. Puedes moverla desde el modo Diseño sin abrir la ventana de opciones, cerrar una ya no cancela la otra, y entrar en combate cierra al instante cualquier vista previa para que nunca se superponga a un lanzamiento real.",
    ["wn_401_layout_chat_route"]  = "Corrección — El engranaje del modo Diseño vuelve a estar en la ventana de chat. Seguía apuntando a los marcos del antiguo skin de chat, sustituido por Chat V4, así que pasar el ratón por el panel de chat no ofrecía ningún acceso a sus ajustes.",
    ["wn_401_bags_v4"]            = "Nuevo — Bags V4 sustituye el antiguo skin de bolsas por una ventana totalmente gestionada por TomoMod: todas las bolsas en una sola cuadrícula, el número de espacios ocupados y totales en la cabecera, tu dinero en el pie y un marco que puedes arrastrar donde quieras. Blizzard sigue a cargo de todas las acciones sobre objetos, así que hacer clic, arrastrar, vender y las descripciones funcionan igual que siempre.",
    ["wn_401_bags_search_sort"]   = "Nuevo — Busca en tus bolsas mientras escribes, por nombre de objeto o por identificador, y alterna la vista entre orden de bolsas, calidad, nombre y nivel de objeto desde el botón de la cabecera. La ordenación es puramente visual: nunca se mueve nada dentro de tus bolsas reales, así que no puede interrumpirse a medias ni entrar en conflicto con el servidor.",
    ["wn_401_bags_sidebar"]       = "Nuevo — Una barra lateral mantiene a la vista tus objetos fijados y recientes. Un clic central fija cualquier objeto y la fijación se guarda con tu perfil; todo lo que llega nuevo a tus bolsas aparece en Recientes. Un clic izquierdo en una miniatura localiza ese objeto en la cuadrícula.",
    ["wn_401_bags_slots"]         = "Nuevo — Los espacios muestran bordes con el color de la calidad, el nivel de objeto en armas y armaduras, una marca en los objetos fijados y un icono atenuado en los bloqueados. Las cantidades y los barridos de reutilización siguen viniendo del propio juego, y las bolsas de componentes se incluyen cuando el cliente las ofrece. Bordes, nivel de objeto y espacios vacíos se desactivan por separado.",
    ["wn_401_bags_native"]        = "Cambio — Abrir y cerrar sigue al juego. Tus atajos de bolsas, el micromenú, los vendedores, el buzón y el banco siguen abriendo la ventana, y los marcos de bolsas de Blizzard se apartan mientras Bags V4 está activo y se devuelven intactos en cuanto lo desactivas.",
    ["wn_401_bags_combat"]        = "Nuevo — Bags V4 nunca crea ni mueve un espacio mientras estás en combate. Todo lo que no puede hacerse con seguridad queda en cola y se aplica en cuanto termina la pelea, mientras los iconos, las cantidades, los bloqueos y las reutilizaciones siguen actualizándose.",
    ["wn_401_bags_migration"]     = "Cambio — Tus ajustes de bolsas existentes se trasladan una vez: opacidad, escala, tamaño de espacio, separación, número de columnas, ordenación, bordes de calidad, nivel de objeto, espacios vacíos, barra de búsqueda y posición de la ventana. Activar y desactivar las bolsas desde el panel, el instalador o un preajuste sigue funcionando mientras se construye la página de opciones dedicada a Bags V4.",
    ["wn_401_bags_display_mode"]  = "Nuevo — Elige cómo se abren tus bolsas. Combinadas mantiene todo en la única ventana de TomoMod; Separadas las devuelve a las ventanas individuales de Blizzard y se aparta por completo, dejando el ajuste de bolsas combinadas del juego en su sitio.",
    ["wn_401_bags_options"]       = "Nuevo — Skins > Bolsas es ahora una página de ajustes en vivo. Modo de visualización, columnas, tamaño y separación de espacios, escala, opacidad, ordenación visual, barra de búsqueda, bordes de calidad, nivel de objeto, espacios vacíos y cuántas miniaturas fijadas y recientes guarda la barra lateral: todo se aplica al instante, sin recargar.",
    ["wn_401_bags_render"]        = "Corrección — Los espacios de bolsa podían aparecer completamente vacíos. Los iconos, las cantidades y los barridos de reutilización los dibuja ahora el propio TomoMod en lugar de depender de partes del botón de bolsa de Blizzard que cambian de una versión del cliente a otra.",
    ["wn_401_bags_interactions"]  = "Corrección — Los espacios vuelven a responder bien al ratón. Pasar por encima, hacer clic y arrastrar podían quedar absorbidos por los adornos de TomoMod; el botón del juego está ahora por encima de todo lo que dibuja TomoMod, las descripciones las muestra el propio accesorio, y el clic central fija el objeto directamente desde la cuadrícula.",
    ["wn_401_bags_empty_quality"] = "Cambio — Los espacios vacíos vuelven a distinguirse con facilidad, y los bordes de calidad se leen mucho mejor: a plena intensidad por encima de la calidad común y más suaves por debajo, sobre un fondo más oscuro. El nivel de objeto se ha movido a la esquina superior izquierda para no quedar bajo la cantidad, y reaparece en los objetos cuyos datos el juego tardaba en entregar.",
    ["wn_401_bags_fit"]           = "Nuevo — La ventana de bolsas ya no puede construirse más grande que tu pantalla. Tu número de columnas se conserva en tu perfil, pero la ventana mostrada se reduce a lo que tu resolución y tu escala pueden contener realmente, en vez de salirse de la pantalla.",
})

TomoMod_RegisterLocale("itIT", {
    ["section_blizzard_auras"]   = "Riquadri aure Blizzard",
    ["info_blizzard_auras"]      = "Controlla i riquadri predefiniti di benefici e penalità di Blizzard senza modificare le aure dei riquadri unità TomoMod. Le modifiche sono immediate e non richiedono un reload.",
    ["opt_blizzard_auras_manage"] = "Lascia che TomoMod gestisca i riquadri aure Blizzard",
    ["opt_blizzard_buffs"]       = "Mostra benefici Blizzard",
    ["opt_blizzard_debuffs"]     = "Mostra penalità Blizzard",
    ["layout_configure"]         = "Configura questo elemento",
    ["wn_401_layout_cogs"]       = "Novità — In modalità Layout compare ora un ingranaggio passando sopra un elemento spostabile. Un clic apre direttamente la relativa pagina delle opzioni TomoMod.",
    ["wn_401_blizzard_auras"]    = "Novità — Interface > Generale consente ora di nascondere separatamente i riquadri benefici e penalità di Blizzard, in tempo reale e senza reload.",
    ["wn_401_chat_v4"]           = "Novità — Chat V4 ricostruisce la presentazione della chat con un'interfaccia TomoMod scura per messaggi, schede ancorate, casella di immissione nativa e una nuova barra laterale, mentre Blizzard continua a gestire consegna, formattazione e interazioni protette.",
    ["wn_401_chat_options"]      = "Novità — Skin > Finestra chat è ora il centro di controllo live di Chat V4. Attivalo, regola opacità dello sfondo e dimensione del testo, scegli il comportamento dei messaggi, personalizza la barra laterale e imposta il limite di righe di Copia chat: ogni modifica si applica subito senza reload.",
    ["wn_401_chat_message_opacity"] = "Novità — L'opacità del riquadro e quella dell'area messaggi sono ora separate. Il secondo cursore modifica solo lo sfondo dietro il testo della chat, fino alla trasparenza completa, senza attenuare schede, barra laterale o casella di immissione; i profili esistenti mantengono l'aspetto precedente.",
    ["wn_401_chat_messages"]     = "Novità — La presentazione può aggiungere o mantenere gli orari, abbreviare i nomi localizzati dei canali, dissolversi dopo due minuti, trasformare le faccine comuni in simboli e colorare per classe le menzioni dei giocatori conosciuti. Cambiare un'opzione ricostruisce le righe esistenti per mantenere coerente tutta la cronologia visibile.",
    ["wn_401_chat_urls"]         = "Novità — I normali indirizzi HTTP(S) e www diventano collegamenti turchesi cliccabili senza alterare i collegamenti Blizzard esistenti. Un clic apre una finestra Ctrl+C focalizzata e la punteggiatura finale resta fuori dal collegamento.",
    ["wn_401_chat_sidebar_options"] = "Novità — Posiziona la barra laterale a sinistra o destra, regola larghezza, dimensione e spaziatura dei pulsanti, mostra o nasconde ogni scorciatoia e scegli da 50 a 1.000 righe per Copia chat. Le precedenti impostazioni dei messaggi di Chat Skin migrano una sola volta a Chat V4.",
    ["wn_401_chat_wiring"]       = "Modifica — Chat V4 è ora l'unico modulo chat pubblico nei valori predefiniti, nel registro moduli, nella pagina iniziale, nell'installazione, nei preset, nelle importazioni dei profili e nel ridimensionamento per risoluzione. I vecchi database della chat restano solo fonti interne di migrazione.",
    ["wn_401_chat_combatlog"]    = "Modifica — Il registro di combattimento usa ora la superficie Chat V4 quando viene selezionato, mentre Blizzard continua a filtrare e formattare prima ogni riga. TomoMod rispecchia solo l'output finale e non sostituisce mai le API del registro di combattimento.",
    ["wn_401_chat_journal_controls"] = "Novità — La barra dei filtri rapidi del registro di combattimento Blizzard è ora ancorata in alto nell'area messaggi di Chat V4, che le riserva spazio. Si nasconde nelle altre schede e torna esattamente alla posizione e visibilità originali quando Chat V4 viene disattivato, senza assegnarla a un altro riquadro né sostituire i filtri.",
    ["wn_401_chat_phase21_polish"] = "Modifica — Le schede rispecchiate restano ora entro il bordo superiore del pannello. La scorciatoia Emote è rimossa da barra laterale, opzioni e layout salvati; Copia chat, Bottino, Impostazioni e Ultimo messaggio sono ordinati in coppie.",
    ["wn_401_chat_tabs"]         = "Novità — Le schede Chat V4 sono ora controlli interattivi disposti da sinistra a destra nella propria barra, incluso un registro di combattimento sganciato. I clic sinistro e destro vengono inoltrati alla scheda Blizzard invisibile, mantenendo selezione e menu contestuali nativi e sincronizzando sottolineatura attiva e messaggi non letti.",
    ["wn_401_chat_native_chrome"] = "Correzione — Sfondi, bordi NineSlice e maniglie di ridimensionamento della chat nativa restano nascosti anche dopo aver selezionato Generale o Registro di combattimento. Chat V4 memorizza l'alfa originale di ogni elemento e lo ripristina esattamente alla disattivazione.",
    ["wn_401_chat_sidebar"]      = "Novità — La barra laterale ridisegnata aggiunge icone personalizzate e colori di stato dinamici per Amici, Gilda, Online/AFK/DND, voce, microfono e audio disattivati, oltre ai conteggi online e ai collegamenti per copia chat, browser bottino, impostazioni TomoMod e ultimo messaggio.",
    ["wn_401_chat_sidebar_assets"] = "Modifica — Le icone della barra laterale usano ora texture trasparenti 64×64 dedicate e sostituibili, incluse le varianti per stato, microfono e audio. I titoli e le descrizioni delle dieci infobolle, oltre al menu In linea/Assente/Non disturbare, sono tradotti in tutte le sei lingue supportate.",
    ["wn_401_chat_copy"]         = "Novità — Copia chat torna come finestra TomoMod completa: legge in tempo reale la scheda Blizzard attiva all'apertura, può essere spostata e ridimensionata, segue la dimensione del carattere della chat e offre i pulsanti tradotti Seleziona tutto e Chiudi, con una barra di scorrimento moderna e un'alternativa compatibile.",
    ["wn_401_chat_copy_clean"]   = "Modifica — La chat copiata diventa testo leggibile conservando colori dei messaggi, indicatori incursione, etichette dei collegamenti e nomi Battle.net disponibili. Grafica e codici di controllo vengono rimossi, i valori protetti ignorati, i testi brevi selezionati automaticamente e la vista si apre sulla riga più recente.",
    ["wn_401_chat_safe"]         = "Modifica — Chat V4 rispecchia la chat di Blizzard invece di sostituirne il percorso protetto. Blizzard mantiene il controllo del filtro del registro di combattimento, nessuna funzione FCF viene agganciata e disattivando Chat V4 viene ripristinata la presentazione nativa.",
    ["wn_401_objective_chrome"]  = "Correzione — Lo sfondo completo e gli sfondi animati delle intestazioni del tracciamento obiettivi Blizzard non possono più riapparire dietro TomoMod dopo un aggiornamento. I valori alfa originali vengono ripristinati quando il tracciamento TomoMod viene disattivato.",
    ["wn_401_castbar_lifecycle"]  = "Correzione — La barra di lancio non sparisce più a metà di un incantesimo lungo. Un istantaneo o un proc scattato mentre stavi lanciando chiudeva la barra dell'incantesimo realmente in corso; ora la chiude soltanto la vera fine di quel lancio.",
    ["wn_401_castbar_identity"]   = "Correzione — Una barra di lancio reagisce ormai solo al proprio incantesimo. L'arresto, il fallimento o l'interruzione di un altro incantesimo non può più chiuderla né farla lampeggiare di rosso, perché ogni barra ricorda quale lancio l'ha aperta e confronta con quello ogni evento di chiusura.",
    ["wn_401_castbar_stale"]      = "Novità — Una barra di lancio che non riceve più notizie dal server si chiude un secondo dopo la fine prevista dell'incantesimo. Un messaggio perso durante un picco di latenza o una riconnessione a metà lancio poteva lasciare una barra bloccata sullo schermo; gli incantesimi potenziati sono esclusi, perché per progetto restano oltre la fine annunciata fino al rilascio.",
    ["wn_401_castbar_preview"]    = "Correzione — La modalità Layout e l'anteprima delle opzioni non si contendono più la barra di lancio del giocatore. Puoi spostarla dalla modalità Layout senza aprire la finestra delle opzioni, chiudere l'una non annulla più l'altra, ed entrare in combattimento chiude subito qualsiasi anteprima perché non copra mai un lancio reale.",
    ["wn_401_layout_chat_route"]  = "Correzione — L'ingranaggio della modalità Layout è di nuovo sulla finestra della chat. Puntava ancora ai riquadri della vecchia skin della chat, sostituita da Chat V4, quindi passare sopra il pannello della chat non offriva alcuna scorciatoia alle sue impostazioni.",
    ["wn_401_bags_v4"]            = "Novità — Bags V4 sostituisce la vecchia skin delle borse con una finestra interamente gestita da TomoMod: tutte le borse in un'unica griglia, il numero di spazi occupati e totali nell'intestazione, il tuo denaro nel piè di pagina e una cornice che puoi trascinare dove vuoi. Blizzard mantiene ogni azione sugli oggetti, quindi clic, trascinamento, vendita e descrizioni funzionano esattamente come prima.",
    ["wn_401_bags_search_sort"]   = "Novità — Cerca nelle borse mentre digiti, per nome oggetto o identificativo, e alterna la vista tra ordine borse, qualità, nome e livello oggetto dal pulsante nell'intestazione. L'ordinamento è puramente visivo: nulla viene mai spostato nelle borse reali, quindi non può interrompersi a metà né entrare in conflitto con il server.",
    ["wn_401_bags_sidebar"]       = "Novità — Una barra laterale tiene in vista gli oggetti fissati e quelli recenti. Un clic centrale fissa qualsiasi oggetto e il fissaggio resta legato al profilo; tutto ciò che arriva di nuovo nelle borse compare tra i Recenti. Un clic sinistro su una miniatura trova l'oggetto nella griglia.",
    ["wn_401_bags_slots"]         = "Novità — Gli spazi mostrano bordi colorati per qualità, il livello oggetto su armi e armature, un segno sugli oggetti fissati e un'icona attenuata su quelli bloccati. Quantità e animazioni di recupero continuano ad arrivare dal gioco stesso, e le borse dei componenti sono incluse quando il client le prevede. Bordi, livello oggetto e spazi vuoti si disattivano singolarmente.",
    ["wn_401_bags_native"]        = "Modifica — L'apertura e la chiusura seguono il gioco. Le scorciatoie delle borse, il micromenu, i mercanti, la cassetta postale e la banca aprono ancora la finestra, e le finestre delle borse di Blizzard vengono messe da parte finché Bags V4 è attivo e restituite intatte appena lo disattivi.",
    ["wn_401_bags_combat"]        = "Novità — Bags V4 non crea né sposta mai uno spazio mentre sei in combattimento. Tutto ciò che non può essere fatto in sicurezza viene messo in coda e applicato appena lo scontro finisce, mentre icone, quantità, blocchi e recuperi continuano ad aggiornarsi.",
    ["wn_401_bags_migration"]     = "Modifica — Le impostazioni delle borse esistenti vengono trasferite una sola volta: opacità, scala, dimensione degli spazi, spaziatura, numero di colonne, ordinamento, bordi di qualità, livello oggetto, spazi vuoti, barra di ricerca e posizione della finestra. Attivare e disattivare le borse da pannello, installer o preset continua a funzionare mentre viene costruita la pagina di opzioni dedicata a Bags V4.",
    ["wn_401_bags_display_mode"]  = "Novità — Scegli come si aprono le borse. Combinate tiene tutto nell'unica finestra TomoMod; Separate le restituisce alle finestre individuali di Blizzard e si fa completamente da parte, rimettendo al suo posto l'impostazione di borse combinate del gioco.",
    ["wn_401_bags_options"]       = "Novità — Skins > Borse è ora una pagina di impostazioni viva. Modalità di visualizzazione, colonne, dimensione e spaziatura degli spazi, scala, opacità, ordinamento visivo, barra di ricerca, bordi di qualità, livello oggetto, spazi vuoti e quante miniature fissate e recenti tiene la barra laterale: tutto si applica all'istante, senza reload.",
    ["wn_401_bags_render"]        = "Correzione — Gli spazi delle borse potevano apparire del tutto vuoti. Icone, quantità e animazioni di recupero ora li disegna TomoMod stesso, invece di affidarsi a parti del pulsante borsa di Blizzard che cambiano da una versione del client all'altra.",
    ["wn_401_bags_interactions"]  = "Correzione — Gli spazi rispondono di nuovo correttamente al mouse. Passaggio, clic e trascinamento potevano essere assorbiti dalla grafica di TomoMod; il pulsante del gioco sta ora sopra tutto ciò che TomoMod disegna, le descrizioni le mostra l'addon stesso, e il clic centrale fissa l'oggetto direttamente dalla griglia.",
    ["wn_401_bags_empty_quality"] = "Modifica — Gli spazi vuoti si distinguono di nuovo con facilità e i bordi di qualità si leggono molto meglio: piena intensità sopra la qualità comune, più tenui sotto, su uno sfondo più scuro. Il livello oggetto è passato in alto a sinistra per non finire sotto la quantità, e ricompare sugli oggetti i cui dati il gioco tardava a fornire.",
    ["wn_401_bags_fit"]           = "Novità — La finestra delle borse non può più essere costruita più grande del tuo schermo. Il numero di colonne resta salvato nel profilo, ma la finestra mostrata viene ridotta a ciò che risoluzione e scala possono davvero contenere, invece di uscire dallo schermo.",
})

TomoMod_RegisterLocale("ptBR", {
    ["section_blizzard_auras"]   = "Quadros de auras da Blizzard",
    ["info_blizzard_auras"]      = "Controla os quadros padrão de benefícios e penalidades da Blizzard sem afetar as auras dos quadros de unidade do TomoMod. As alterações são imediatas e não exigem recarregamento.",
    ["opt_blizzard_auras_manage"] = "Permitir que o TomoMod gerencie os quadros de auras da Blizzard",
    ["opt_blizzard_buffs"]       = "Mostrar benefícios da Blizzard",
    ["opt_blizzard_debuffs"]     = "Mostrar penalidades da Blizzard",
    ["layout_configure"]         = "Configurar este elemento",
    ["wn_401_layout_cogs"]       = "Novo — O modo Layout agora mostra uma engrenagem ao passar o mouse sobre um elemento móvel. Um clique abre diretamente a página de opções correspondente do TomoMod.",
    ["wn_401_blizzard_auras"]    = "Novo — Interface > Geral agora permite ocultar separadamente os quadros de benefícios e penalidades da Blizzard, ao vivo e sem recarregar.",
    ["wn_401_chat_v4"]           = "Novo — O Chat V4 reconstrói a apresentação do bate-papo com uma interface escura do TomoMod para mensagens, abas encaixadas, caixa de entrada nativa e uma nova barra lateral, enquanto a Blizzard continua responsável pela entrega, formatação e interações seguras.",
    ["wn_401_chat_options"]      = "Novo — Skins > Janela de bate-papo agora é o centro de controle ao vivo do Chat V4. Ative, ajuste a opacidade do fundo e o tamanho da fonte, escolha o comportamento das mensagens, personalize a barra lateral e defina o limite de linhas da cópia; cada alteração é aplicada imediatamente e sem recarregar.",
    ["wn_401_chat_message_opacity"] = "Novo — A opacidade do quadro e a da área de mensagens agora são independentes. O segundo controle altera apenas o fundo atrás do texto do bate-papo, até ficar totalmente transparente, sem esmaecer abas, barra lateral ou caixa de entrada; os perfis existentes mantêm a aparência anterior.",
    ["wn_401_chat_messages"]     = "Novo — A apresentação pode adicionar ou preservar horários, abreviar nomes localizados de canais, desaparecer após dois minutos, transformar emoticons comuns em símbolos e colorir por classe as menções a jogadores conhecidos. Alterar uma opção reconstrói as linhas existentes para manter todo o histórico visível consistente.",
    ["wn_401_chat_urls"]         = "Novo — Endereços HTTP(S) e www comuns viram links turquesa clicáveis sem alterar os hiperlinks existentes da Blizzard. Clicar abre uma janela focada para Ctrl+C e a pontuação no fim da frase fica fora do link.",
    ["wn_401_chat_sidebar_options"] = "Novo — Coloque a barra lateral à esquerda ou direita, ajuste largura, tamanho e espaçamento dos botões, mostre ou oculte cada atalho e escolha entre 50 e 1.000 linhas para a cópia do bate-papo. As configurações antigas de mensagens do Chat Skin migram uma única vez para o Chat V4.",
    ["wn_401_chat_wiring"]       = "Mudança — O Chat V4 agora é o único módulo público de bate-papo nos padrões, no registro de módulos, no painel inicial, no instalador, nas predefinições, nas importações de perfil e no ajuste por resolução. Os bancos de dados antigos do bate-papo permanecem apenas como fontes internas de migração.",
    ["wn_401_chat_combatlog"]    = "Mudança — O registro de combate agora usa a superfície do Chat V4 quando selecionado, enquanto a Blizzard continua filtrando e formatando primeiro cada linha. O TomoMod apenas espelha a saída final e nunca substitui as APIs do registro de combate.",
    ["wn_401_chat_journal_controls"] = "Novo — A barra de filtros rápidos do registro de combate da Blizzard agora fica ancorada no topo da área de mensagens do Chat V4, que reserva espaço para ela. Ela se oculta nas outras abas e volta exatamente à posição e visibilidade originais quando o Chat V4 é desativado, sem vinculá-la a outro quadro nem substituir os filtros.",
    ["wn_401_chat_phase21_polish"] = "Mudança — As abas espelhadas agora ficam dentro da borda superior do painel. O atalho Emotes foi removido da barra lateral, das opções e dos layouts salvos; Copiar bate-papo, Saques, Configurações e Última mensagem ficam organizados em pares.",
    ["wn_401_chat_tabs"]         = "Novo — As abas do Chat V4 agora são controles interativos organizados da esquerda para a direita em sua própria barra, incluindo um registro de combate desencaixado. Cliques esquerdo e direito são encaminhados à aba invisível da Blizzard, preservando a seleção e os menus de contexto nativos enquanto o sublinhado ativo e as mensagens não lidas ficam sincronizados.",
    ["wn_401_chat_native_chrome"] = "Corrigido — Fundos, bordas NineSlice e alças de redimensionamento do chat nativo permanecem ocultos mesmo após selecionar Geral ou Registro de combate. O Chat V4 salva o alfa original de cada elemento e o restaura exatamente ao ser desativado.",
    ["wn_401_chat_sidebar"]      = "Novo — A barra lateral redesenhada adiciona ícones personalizados e cores de estado dinâmicas para Amigos, Guilda, Online/AFK/DND, voz, microfone e áudio desativados, além de contagens online e atalhos para cópia do bate-papo, navegador de saques, configurações do TomoMod e última mensagem.",
    ["wn_401_chat_sidebar_assets"] = "Mudança — Os ícones da barra lateral agora usam texturas transparentes 64×64 dedicadas e substituíveis, incluindo variantes de status, microfone e áudio. Os títulos e descrições das dez dicas, além do menu Online/Ausente/Não perturbe, estão traduzidos nos seis idiomas compatíveis.",
    ["wn_401_chat_copy"]         = "Novo — Copiar bate-papo volta como uma janela completa do TomoMod: lê ao vivo a aba ativa da Blizzard ao abrir, pode ser movida e redimensionada, acompanha o tamanho da fonte do bate-papo e oferece botões traduzidos para Selecionar tudo e Fechar, com uma barra de rolagem moderna e uma alternativa compatível.",
    ["wn_401_chat_copy_clean"]   = "Mudança — O bate-papo copiado vira texto legível e preserva as cores das mensagens, marcadores de raide, rótulos de links e nomes Battle.net disponíveis. Elementos gráficos e códigos de controle são removidos, valores protegidos são ignorados, textos curtos são selecionados automaticamente e a visualização abre na linha mais recente.",
    ["wn_401_chat_safe"]         = "Mudança — O Chat V4 espelha o bate-papo da Blizzard em vez de substituir seu caminho seguro. A Blizzard mantém o controle da filtragem do registro de combate, nenhuma função FCF é vinculada e desativar o Chat V4 restaura a apresentação nativa.",
    ["wn_401_objective_chrome"]  = "Corrigido — O fundo completo e os fundos animados dos cabeçalhos do rastreador de objetivos da Blizzard não podem mais reaparecer atrás do TomoMod após uma atualização. Os valores alfa originais são restaurados quando o rastreador do TomoMod é desativado.",
    ["wn_401_castbar_lifecycle"]  = "Correção — Sua barra de conjuração não some mais no meio de uma magia longa. Uma magia instantânea ou um proc disparado enquanto você conjurava fechava a barra da magia que estava realmente em andamento; agora só o fim verdadeiro dessa conjuração a fecha.",
    ["wn_401_castbar_identity"]   = "Correção — Uma barra de conjuração só reage à própria conjuração. A parada, a falha ou a interrupção de outra magia não pode mais fechá-la nem fazê-la piscar em vermelho, porque cada barra lembra qual conjuração a abriu e confere cada evento de encerramento com essa identidade.",
    ["wn_401_castbar_stale"]      = "Novo — Uma barra de conjuração que para de receber notícias do servidor se fecha um segundo depois do fim previsto da magia. Uma mensagem perdida num pico de latência ou uma reconexão no meio da conjuração podia deixar uma barra congelada na tela; magias de intensificação ficam de fora, já que devem se manter além do fim anunciado até você soltar.",
    ["wn_401_castbar_preview"]    = "Correção — O modo Layout e a prévia das opções não disputam mais a barra de conjuração do jogador. Você pode movê-la pelo modo Layout sem abrir a janela de opções, fechar uma não cancela mais a outra, e entrar em combate fecha qualquer prévia na hora para que ela nunca fique por cima de uma conjuração real.",
    ["wn_401_layout_chat_route"]  = "Correção — A engrenagem do modo Layout voltou à janela de bate-papo. Ela ainda apontava para os quadros da antiga skin do bate-papo, substituída pelo Chat V4, então passar o mouse sobre o painel não oferecia nenhum atalho para as configurações.",
    ["wn_401_bags_v4"]            = "Novo — O Bags V4 substitui a antiga skin das bolsas por uma janela totalmente gerenciada pelo TomoMod: todas as bolsas em uma única grade, o número de espaços ocupados e totais no cabeçalho, seu dinheiro no rodapé e um quadro que você arrasta para onde quiser. A Blizzard continua responsável por todas as ações com itens, então clicar, arrastar, vender e as dicas funcionam exatamente como antes.",
    ["wn_401_bags_search_sort"]   = "Novo — Busque nas bolsas enquanto digita, por nome do item ou identificador, e alterne a exibição entre ordem das bolsas, qualidade, nome e nível do item pelo botão do cabeçalho. A ordenação é apenas visual: nada é movido dentro das suas bolsas reais, então ela não pode ser interrompida pela metade nem entrar em conflito com o servidor.",
    ["wn_401_bags_sidebar"]       = "Novo — Uma barra lateral mantém à vista seus itens fixados e recentes. O clique do meio fixa qualquer item e a fixação fica salva no seu perfil; tudo que chega de novo nas bolsas aparece em Recentes. O clique esquerdo em uma miniatura localiza o item na grade.",
    ["wn_401_bags_slots"]         = "Novo — Os espaços mostram bordas coloridas por qualidade, o nível do item em armas e armaduras, uma marca nos itens fixados e um ícone esmaecido nos bloqueados. As quantidades e as animações de recarga continuam vindo do próprio jogo, e as bolsas de reagentes são incluídas quando o cliente as oferece. Bordas, nível do item e espaços vazios podem ser desativados separadamente.",
    ["wn_401_bags_native"]        = "Mudança — Abrir e fechar acompanha o jogo. Seus atalhos de bolsa, o micromenu, os vendedores, a caixa de correio e o banco continuam abrindo a janela, e os quadros de bolsa da Blizzard ficam guardados enquanto o Bags V4 está ativo e são devolvidos intactos assim que você o desativa.",
    ["wn_401_bags_combat"]        = "Novo — O Bags V4 nunca cria nem move um espaço enquanto você está em combate. Tudo que não pode ser feito com segurança entra na fila e é aplicado assim que a luta termina, enquanto ícones, quantidades, bloqueios e recargas continuam se atualizando.",
    ["wn_401_bags_migration"]     = "Mudança — Suas configurações de bolsa existentes são transferidas uma vez: opacidade, escala, tamanho do espaço, espaçamento, número de colunas, ordenação, bordas de qualidade, nível do item, espaços vazios, barra de busca e posição da janela. Ligar e desligar as bolsas pelo painel, pelo instalador ou por uma predefinição continua funcionando enquanto a página de opções dedicada ao Bags V4 é construída.",
    ["wn_401_bags_display_mode"]  = "Novo — Escolha como suas bolsas abrem. Combinadas mantém tudo na única janela do TomoMod; Separadas as devolve às janelas individuais da Blizzard e sai completamente do caminho, recolocando no lugar a própria configuração de bolsas combinadas do jogo.",
    ["wn_401_bags_options"]       = "Novo — Skins > Bolsas agora é uma página de configurações ao vivo. Modo de exibição, colunas, tamanho e espaçamento dos espaços, escala, opacidade, ordenação visual, barra de busca, bordas de qualidade, nível do item, espaços vazios e quantas miniaturas fixadas e recentes a barra lateral guarda: tudo se aplica na hora, sem recarregar.",
    ["wn_401_bags_render"]        = "Correção — Espaços de bolsa podiam aparecer completamente vazios. Os ícones, as quantidades e as animações de recarga agora são desenhados pelo próprio TomoMod, em vez de depender de partes do botão de bolsa da Blizzard que mudam de uma versão do cliente para outra.",
    ["wn_401_bags_interactions"]  = "Correção — Os espaços voltam a responder direito ao mouse. Passar o cursor, clicar e arrastar podiam ser absorvidos pelos elementos gráficos do TomoMod; o botão do jogo agora fica acima de tudo que o TomoMod desenha, as dicas são exibidas pelo próprio addon, e o clique do meio fixa o item direto da grade.",
    ["wn_401_bags_empty_quality"] = "Mudança — Os espaços vazios voltam a se distinguir com facilidade, e as bordas de qualidade ficam bem mais legíveis: força total acima da qualidade comum, mais suaves abaixo, sobre um fundo mais escuro. O nível do item foi para o canto superior esquerdo, deixando de ficar sob a quantidade, e reaparece em itens cujos dados o jogo demorava a entregar.",
    ["wn_401_bags_fit"]           = "Novo — A janela das bolsas não pode mais ser construída maior que a sua tela. Seu número de colunas continua salvo no perfil, mas a janela exibida é reduzida ao que sua resolução e escala conseguem realmente comportar, em vez de passar da borda da tela.",
